using System.Globalization;
using System.Text.Json.Serialization;

namespace QueryForge.Api;

// Data-backed chart definitions; values originate from dataset rows, never generated by an LLM.
[JsonConverter(typeof(JsonStringEnumConverter<ChartKind>))]
public enum ChartKind { CountByCategory, SumByCategory, Histogram }
public sealed record ChartRequest(
    ChartKind Kind,
    string Column,
    string? Measure = null,
    int TopN = 8,
    bool ExcludeFlaggedRows = true);
public sealed record ChartPoint(string Label, decimal Value, int Records);
public sealed record ChartResult(
    ChartKind Kind,
    string Title,
    string CategoryColumn,
    string? MeasureColumn,
    string Unit,
    int IncludedRows,
    int ExcludedRows,
    int InvalidNumericRows,
    bool ExcludeFlaggedRows,
    string DatasetSha256,
    IReadOnlyList<ChartPoint> Points,
    IReadOnlyList<string> Notes);
public sealed record ChartSuggestion(ChartKind Kind, string Column, string? Measure, string Reason);
public sealed record IssueSummary(string Code, string Severity, int Count);
public sealed record DataInsights(
    Guid DatasetId,
    string DatasetSha256,
    int RowCount,
    int RowsWithIssues,
    decimal QualityScorePercent,
    IReadOnlyList<IssueSummary> Issues,
    IReadOnlyList<ChartSuggestion> SuggestedCharts,
    IReadOnlyList<string> ImportantNotes);
public sealed record EtlSuggestion(
    string Title, string Reason, string Risk, IReadOnlyList<TransformStep> Steps);
public sealed record AdvisoryReport(
    Guid DatasetId,
    string DatasetSha256,
    string GeneratedBy,
    bool AiEnabled,
    string ExecutiveSummary,
    IReadOnlyList<string> Evidence,
    IReadOnlyList<EtlSuggestion> SuggestedTransformations,
    IReadOnlyList<string> RequiredHumanDecisions);

public sealed class ChartValidationException(string message) : Exception(message);

public interface IDataInsightsService
{
    DataInsights GetInsights(DatasetEntity source);
    ChartResult BuildChart(DatasetEntity source, ChartRequest request);
    AdvisoryReport BuildAdvisoryReport(DatasetEntity source);
}

public sealed class DeterministicDataInsightsService : IDataInsightsService
{
    private const NumberStyles DecimalStyles =
        NumberStyles.AllowLeadingSign | NumberStyles.AllowDecimalPoint |
        NumberStyles.AllowLeadingWhite | NumberStyles.AllowTrailingWhite;

    public DataInsights GetInsights(DatasetEntity source)
    {
        var headers = source.Headers;
        var rows = source.Rows;
        var report = source.Report;
        var issues = report.Issues
            .GroupBy(x => new { x.Code, x.Severity })
            .Select(g => new IssueSummary(g.Key.Code, g.Key.Severity, g.Count()))
            .OrderByDescending(x => x.Count).ThenBy(x => x.Code, StringComparer.Ordinal)
            .ToList();

        var suggested = new List<ChartSuggestion>();
        // Suggest low-cardinality categorical charts and reliable decimal histograms.
        foreach (var column in headers)
        {
            int nonEmpty = rows.Count(r => !string.IsNullOrWhiteSpace(r.GetValueOrDefault(column)));
            if (nonEmpty == 0) continue;
            int numeric = rows.Count(r => TryDecimal(r.GetValueOrDefault(column, ""), out _));
            int distinct = rows.Select(r => r.GetValueOrDefault(column, "").Trim())
                .Where(x => x.Length != 0).Distinct(StringComparer.OrdinalIgnoreCase).Take(31).Count();
            if (numeric == nonEmpty && nonEmpty >= 2)
                suggested.Add(new(ChartKind.Histogram, column, null,
                    "Values parse consistently as invariant-culture decimals."));
            else if (distinct is >= 1 and <= 30 && numeric < nonEmpty)
                suggested.Add(new(ChartKind.CountByCategory, column, null,
                    "This column has a manageable number of distinct categories."));
            // Do not cut off the search before reaching useful columns later in the CSV.
        }

        // Present meaningful business dimensions first; identifiers are usually poor default charts.
        static int Rank(ChartSuggestion suggestion)
        {
            string name = suggestion.Column.ToLowerInvariant();
            if (name is "region" or "category" or "status" or "currency" or
                "department" or "country" or "product") return 20;
            if (suggestion.Kind == ChartKind.Histogram &&
                name is "amount" or "revenue" or "quantity" or "price") return 18;
            if (name is "id" or "order_id" or "orderid" or "customer_id") return -10;
            return suggestion.Kind == ChartKind.Histogram ? 10 : 5;
        }
        var rankedCharts = suggested.OrderByDescending(Rank)
            .ThenBy(x => x.Column, StringComparer.Ordinal).Take(6).ToList();

        var score = rows.Count == 0 ? 100m :
            Math.Round(100m * (rows.Count - report.RowsWithIssues) / rows.Count, 2);
        return new(source.Id, source.Sha256, rows.Count, report.RowsWithIssues,
            score, issues, rankedCharts,
            [
                "Quality score means the percentage of rows without any reported issue; it does not certify data correctness.",
                "Chart previews exclude all flagged rows by default; users can explicitly include them.",
                "Inference is heuristic. Confirm column types, measure units, and intended business meaning."
            ]);
    }

    public ChartResult BuildChart(DatasetEntity source, ChartRequest request)
    {
        ArgumentNullException.ThrowIfNull(source);
        ArgumentNullException.ThrowIfNull(request);
        var headers = source.Headers;
        if (!headers.Contains(request.Column, StringComparer.Ordinal))
            throw new ChartValidationException("Choose an exact existing category or numeric column.");
        if (!Enum.IsDefined(request.Kind))
            throw new ChartValidationException("Unknown chart type.");
        if (request.TopN is < 1 or > 20)
            throw new ChartValidationException("TopN must be between 1 and 20.");

        if (request.Kind == ChartKind.SumByCategory &&
            (string.IsNullOrWhiteSpace(request.Measure) ||
             !headers.Contains(request.Measure, StringComparer.Ordinal)))
            throw new ChartValidationException("Choose an existing numeric measure to sum.");

        var rows = source.Rows;
        var flagged = source.Report.Issues.Select(i => i.RowNumber).ToHashSet();
        var selected = rows.Select((r, i) => new { Row = r, Index = i + 2 })
            .Where(x => !request.ExcludeFlaggedRows || !flagged.Contains(x.Index))
            .Select(x => x.Row).ToArray();
        var notes = new List<string>
        {
            request.ExcludeFlaggedRows
                ? "All rows with any quality issue were excluded; warnings and errors are both exclusionary."
                : "Flagged rows were included by user choice; results may contain invalid data.",
            "Unparseable numeric values are excluded from numeric aggregation and counted separately."
        };
        string unit = "records";
        int invalid = 0;
        List<ChartPoint> points;
        switch (request.Kind)
        {
            case ChartKind.CountByCategory:
                points = selected.GroupBy(r =>
                    string.IsNullOrWhiteSpace(r.GetValueOrDefault(request.Column))
                        ? "(missing)" : r.GetValueOrDefault(request.Column, "").Trim(),
                        StringComparer.OrdinalIgnoreCase)
                    .Select(g => new ChartPoint(g.Key, g.Count(), g.Count()))
                    .OrderByDescending(x => x.Value).ThenBy(x => x.Label, StringComparer.Ordinal)
                    .ToList();
                points = TakeTopWithOther(points, request.TopN);
                break;
            case ChartKind.SumByCategory:
                // Never sum monetary measures across mixed/unknown currencies.
                var currency = headers.FirstOrDefault(h =>
                    h.Equals("currency", StringComparison.OrdinalIgnoreCase));
                if (currency is not null)
                {
                    var units = selected.Select(r => r.GetValueOrDefault(currency, "").Trim())
                        .Distinct(StringComparer.OrdinalIgnoreCase).ToArray();
                    if (units.Length != 1 || string.IsNullOrWhiteSpace(units[0]))
                        throw new ChartValidationException(
                            "Cannot sum records with mixed or missing currencies. Filter/clean currencies first.");
                    unit = units[0].ToUpperInvariant();
                }
                else
                {
                    unit = "unspecified units";
                    notes.Add("No explicit currency column: confirm measure unit before business use.");
                }

                var valid = new List<(string Category, decimal Value)>();
                foreach (var row in selected)
                {
                    if (!TryDecimal(row.GetValueOrDefault(request.Measure!, ""), out var value))
                    {
                        invalid++;
                        continue;
                    }
                    var category = row.GetValueOrDefault(request.Column, "").Trim();
                    valid.Add((category.Length == 0 ? "(missing)" : category, value));
                }
                points = valid.GroupBy(x => x.Category, StringComparer.OrdinalIgnoreCase)
                    .Select(g => new ChartPoint(g.Key, g.Sum(x => x.Value), g.Count()))
                    .OrderByDescending(x => x.Value).ThenBy(x => x.Label, StringComparer.Ordinal)
                    .ToList();
                points = TakeTopWithOther(points, request.TopN);
                break;
            case ChartKind.Histogram:
                var numbers = new List<decimal>();
                foreach (var row in selected)
                {
                    if (TryDecimal(row.GetValueOrDefault(request.Column, ""), out var value))
                        numbers.Add(value);
                    else invalid++;
                }
                if (numbers.Count == 0) points = [];
                else
                {
                    decimal min = numbers.Min(), max = numbers.Max();
                    if (min == max)
                        points = [new($"{min.ToString("0.##", CultureInfo.InvariantCulture)}", numbers.Count, numbers.Count)];
                    else
                    {
                        int bins = Math.Clamp(request.TopN, 2, 12);
                        decimal width = (max - min) / bins;
                        var buckets = new int[bins];
                        foreach (var n in numbers)
                        {
                            var position = (int)Math.Min(bins - 1,
                                decimal.Truncate((n - min) / width));
                            buckets[position]++;
                        }
                        points = Enumerable.Range(0, bins).Select(i =>
                            new ChartPoint(
                                $"{(min + i * width).ToString("0.##", CultureInfo.InvariantCulture)}–{(min + (i + 1) * width).ToString("0.##", CultureInfo.InvariantCulture)}",
                                buckets[i], buckets[i])).ToList();
                    }
                }
                break;
            default:
                throw new ChartValidationException("Unsupported chart type.");
        }
        var title = request.Kind switch
        {
            ChartKind.CountByCategory => $"Records by {request.Column}",
            ChartKind.SumByCategory => $"{request.Measure} by {request.Column}",
            _ => $"Distribution of {request.Column}"
        };
        return new(request.Kind, title, request.Column, request.Measure, unit, selected.Length,
            rows.Count - selected.Length, invalid, request.ExcludeFlaggedRows, source.Sha256,
            points, notes);
    }

    public AdvisoryReport BuildAdvisoryReport(DatasetEntity source)
    {
        var insight = GetInsights(source);
        var suggestions = new List<EtlSuggestion>();
        var headers = source.Headers;
        var report = source.Report;
        if (report.Columns.Any(p => p.Missing > 0))
        {
            var candidate = report.Columns.First(p => p.Missing > 0);
            suggestions.Add(new("Review missing values",
                $"{candidate.Name} contains {candidate.Missing} empty values.",
                "Dropping or filling can change analysis; no automatic repair is performed.",
                [new(TransformOperation.DropMissing, candidate.Name)]));
        }
        if (report.Issues.Any(i => i.Code == "DUPLICATE_ID"))
        {
            var column = report.Issues.First(i => i.Code == "DUPLICATE_ID").Column;
            suggestions.Add(new("Inspect duplicate keys",
                $"Repeated identifier values were found in {column}.",
                "Removing duplicates discards later records; verify key semantics.",
                [new(TransformOperation.DropDuplicates, column)]));
        }
        if (report.Issues.Any(i => i.Code == "MIXED_CURRENCY"))
            suggestions.Add(new("Separate currencies before aggregating",
                "Mixed currency codes were detected in the source.",
                "No exchange rate, conversion or preferred base currency is assumed.",
                []));
        var score = insight.QualityScorePercent.ToString("0.##", CultureInfo.InvariantCulture);
        var summary = $"{source.FileName} contains {insight.RowCount} records. " +
            $"{insight.RowsWithIssues} records have one or more flagged issues; " +
            $"the defined row-level quality score is {score}%. " +
            (insight.Issues.Count == 0
                ? "No issues were detected by the currently enabled rules."
                : $"The most frequent reported issue is {insight.Issues[0].Code} ({insight.Issues[0].Count} occurrences).");
        return new(source.Id, source.Sha256,
            "QueryForge deterministic evidence advisor", false,
            summary,
            [
                $"Dataset SHA-256: {source.Sha256}",
                $"Analyzed rows: {insight.RowCount}; rows with issues: {insight.RowsWithIssues}",
                $"Report uses {insight.Issues.Count} reported issue types and no external model."
            ],
            suggestions,
            [
                "Confirm source column types, currency units and expected row-level quality policy.",
                "Preview ETL changes and inspect affected records before approving any destructive operation.",
                "This is a rule-based planning assistant, NOT an autonomous AI agent or an LLM-generated report."
            ]);
    }

    private static bool TryDecimal(string text, out decimal value) =>
        decimal.TryParse(text, DecimalStyles, CultureInfo.InvariantCulture, out value);

    private static List<ChartPoint> TakeTopWithOther(List<ChartPoint> points, int topN)
    {
        if (points.Count <= topN) return points;
        var kept = points.Take(topN).ToList();
        var rest = points.Skip(topN).ToArray();
        kept.Add(new("(other categories)", rest.Sum(x => x.Value), rest.Sum(x => x.Records)));
        return kept;
    }
}
